// CSD_RATIONALE_BEGIN
// Building on best known result (attempt 24: 34.7%/79.6%) using
// GenerateWithPrefixAndManagedSpan, with two targeted improvements:
//
// 1. Stronger guidance against the primary syntax failure: model outputs {variable}
//    with curly braces instead of bare variable names (e.g. {n1} instead of n1).
//    The guidance now shows the exact transformation explicitly and excludes currency
//    placeholders ({cur}, $) that appear as strings in prompts but are not numeric.
//    It also reinforces int() wrapping and // for integer division.
//
// 2. Higher prefix budget (87% vs 78%) to minimize constrained intervention.
//    All prior attempts show correct_with_activity 0/49: every example where the
//    constrained helper actively stepped inside the span produced a wrong answer.
//    Free generation is semantically superior; the managed span is used only as a
//    safety net to force span entry and reliable closure. Raising the budget to 87%
//    gives the model 783 free steps (vs 702), deferring constrained mode longer.
//    The remaining 117 steps are ample for closing a ~6-token arithmetic expression.
//
// Parameters: prefixBudget=87%, boostAmount=8.0, narrowThreshold=6
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   - Initialization: directly from precondition
//     (insideConstrained ==> parser.IsValidPrefix(currentConstrained)).
//   - After GenerateWithPrefixAndManagedSpan: the helper's postcondition directly
//     guarantees (!insideConstrainedOut ==> currentConstrainedOut == []) and
//     (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)).
//   - No further branches can violate this invariant after the helper returns.
//   - The maxSteps==0 early-exit branch returns the original state, which satisfies
//     the invariant by precondition.
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + maxSteps, cost <= maxSteps
//   - GenerateWithPrefixAndManagedSpan postcondition guarantees
//     |generated| <= |generatedPrefix| + maxSteps directly.
//   - We set cost := maxSteps, so cost == maxSteps <= maxSteps.
//   - Visible output growth is bounded by consumed token budget: every token appended
//     to generated costs one step from the budget; EOS, rejected suffixes, and delimiter
//     tokens count against the budget but do not grow visible output beyond their cost,
//     so the length bound is preserved.
//   - Liveness (maxSteps==0 || cost>0 || state changed): when maxSteps > 0, we set
//     cost := maxSteps > 0, satisfying cost > 0. When maxSteps == 0, the disjunct
//     maxSteps==0 is true and the postcondition is trivially satisfied.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  var guidance: string :=
    "Solve this math problem step by step.\n\n" +
    "At the very end, write your FINAL ANSWER as: <<int(expression)>>\n\n" +
    "CRITICAL rules for the expression inside << >>:\n" +
    "- REMOVE curly braces from variable names: {n1} becomes n1, {price} becomes price, {rate} becomes rate\n" +
    "- Do NOT include currency symbols ({cur}, $, EUR) - they are strings, not numbers\n" +
    "- Use // for integer division when the result must be a whole number\n" +
    "- Wrap the entire expression in int(): write <<int(expr)>> not <<expr>>\n" +
    "- Only allowed in expr: numbers, plain variable names, +, -, *, /, //, %, (, ), int()\n" +
    "- Forbidden: {braces}, ** exponentiation, LaTeX notation ($...$ or \\frac)\n\n" +
    "Correct examples:\n" +
    "<<int(n * price + bonus)>>\n" +
    "<<int((a + b) * 100 // total)>>\n" +
    "<<int(rate * hours - deduction)>>\n" +
    "<<int(n1 * p1 + n2 * p2 + n3 * p3)>>";
  helpers.AppendTaskGuidance(lm, guidance);

  var prefixBudget: nat := (maxSteps * 87) / 100;
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  var boostAmount: real := 8.0;
  var narrowThreshold: nat := 6;

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget, validTokenGroups, boostAmount, narrowThreshold, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;

  cost := maxSteps;
}

